changeSet.sql:
INSERT INTO neonatal_transfer_maternal ( neonatal_transfer_id, mother_alive, obstetric_gravida, obstetric_parity, pregnancy_type, anc_screening, pathologies_during_pregnancy, pregnancy_other_pathologies, pregnancy_treatment, blood_group, rh_factor, hiv_status, hiv_regimen, hiv_recent_vl, hiv_cd4_count, hiv_opportunistic_infections, tetanus_vaccine_doses, maternal_illicit_drug_history, rom_at, af_quality, af_quantity, fever_timing, steroid_doses, last_steroid_dose_at, mgso4_at, mode_of_delivery, labor_complications, labor_complications_other, maternal_anesthesia, maternal_anesthesia_other, maternal_antibiotics, other_drugs, sepsis_risk_factors ) SELECT neonatal_transfer_id, mother_alive, obstetric_gravida, obstetric_parity, pregnancy_type, anc_screening, pathologies_during_pregnancy, pregnancy_other_pathologies, pregnancy_treatment, blood_group, rh_factor, hiv_status, hiv_regimen, hiv_recent_vl, hiv_cd4_count, hiv_opportunistic_infections, tetanus_vaccine_doses, maternal_illicit_drug_history, rom_at, af_quality, af_quantity, fever_timing, steroid_doses, last_steroid_dose_at, mgso4_at, mode_of_delivery, labor_complications, labor_complications_other, maternal_anesthesia, maternal_anesthesia_other, maternal_antibiotics, other_drugs, sepsis_risk_factors FROM neonatal_transfers nt WHERE NOT EXISTS ( SELECT 1 FROM neonatal_transfer_maternal m WHERE m.neonatal_transfer_id = nt.neonatal_transfer_id );
INSERT INTO neonatal_transfer_clinical ( neonatal_transfer_id, resuscitation_at_birth, resuscitation_methods, apgar_1min, apgar_5min, apgar_10min, hie, hie_grade, allergies, immunization, immunization_details, vitamin_k, tetracycline_eye_ointment, surfactant, chief_complaint_details, spo2_preductal, spo2_postductal, condition_temp, condition_hr, condition_rr, condition_bp, neurological_status, seizures, adverse_events_24h, diagnosis_1, diagnosis_2, diagnosis_3, diagnosis_4 ) SELECT neonatal_transfer_id, resuscitation_at_birth, resuscitation_methods, apgar_1min, apgar_5min, apgar_10min, hie, hie_grade, allergies, immunization, immunization_details, vitamin_k, tetracycline_eye_ointment, surfactant, chief_complaint_details, spo2_preductal, spo2_postductal, condition_temp, condition_hr, condition_rr, condition_bp, neurological_status, COALESCE(seizures, 0), adverse_events_24h, diagnosis_1, diagnosis_2, diagnosis_3, diagnosis_4 FROM neonatal_transfers nt WHERE NOT EXISTS ( SELECT 1 FROM neonatal_transfer_clinical c WHERE c.neonatal_transfer_id = nt.neonatal_transfer_id );
INSERT INTO neonatal_transfer_management ( neonatal_transfer_id, respiratory_support, ventilation_settings, blood_gas_analysis, iv_fluid_vol, passed_urine, inotropes, inotropes_specify, peripheral_iv, central_iv, intraosseous_line, antibiotic1_name, antibiotic1_doses, antibiotic1_durations, antibiotic2_name, antibiotic2_doses, antibiotic2_durations, arvs, npo, last_feed_time, last_feed_amount, feed_vol, feed_type, passed_stool, nasogastric_tube, lab_glucose, lab_fbc, lab_hb, lab_wbc, lab_platelets, lab_crp, lab_bili_total, lab_bili_direct, lab_ue, lab_cultures, fbc_done, imaging_results_available, imaging_results, pain_sedation_drugs, imaging_report_attached, lab_reports_attached, clinical_management_summary ) SELECT neonatal_transfer_id, respiratory_support, ventilation_settings, blood_gas_analysis, iv_fluid_vol, passed_urine, inotropes, inotropes_specify, peripheral_iv, central_iv, intraosseous_line, antibiotic1_name, antibiotic1_doses, antibiotic1_durations, antibiotic2_name, antibiotic2_doses, antibiotic2_durations, arvs, npo, last_feed_time, last_feed_amount, feed_vol, feed_type, passed_stool, nasogastric_tube, lab_glucose, lab_fbc, lab_hb, lab_wbc, lab_platelets, lab_crp, lab_bili_total, lab_bili_direct, lab_ue, lab_cultures, fbc_done, imaging_results_available, imaging_results, pain_sedation_drugs, COALESCE(imaging_report_attached, 0), COALESCE(lab_reports_attached, 0), clinical_management_summary FROM neonatal_transfers nt WHERE NOT EXISTS ( SELECT 1 FROM neonatal_transfer_management m WHERE m.neonatal_transfer_id = nt.neonatal_transfer_id );
